            "System/System_Title",
        };

        internal static int Count => All.Length;

        /// <summary>按前缀找第一个剧本（跳转菜单里「跳到某章开头」用）。</summary>
        internal static int IndexOfPrefix(string prefix)
        {
            if (string.IsNullOrEmpty(prefix)) return -1;
            for (int i = 0; i < All.Length; i++)
                if (All[i].StartsWith(prefix, System.StringComparison.OrdinalIgnoreCase)) return i;
            return -1;
        }
    }
